INSERT INTO comments (page, name, text, created_at, ip_hash) VALUES
('diary', 'stari_spomeni', 'Намерих "Последната Глогинка", докато се лутах из дигиталните руини на стария интернет... Все едно отворих забравен албум в мазето на душата си. Благодаря, че съживихте нещо толкова лично и толкова колективно едновременно. 🌸', '2025-05-15T19:14:00.000Z', 'seed'),
('diary', 'retro_lili.dir.bg', 'Казвам се Лили и съм от поколението на лъскавите гел-снимки и blink-текстовете. Попаднах на Глогинка през Neocities и направо сърцето ми прескочи... така мирише интернетът на младостта. 💾💖', '2025-05-15T14:01:00.000Z', 'seed'),
('library', 'bobi_mnogo_vajniq', 'О боже... направо не мога да повярвам, че някога съм си слагал подобни неща като статус. 😅 Добре че няма архив на Skype...', '2025-05-25T19:14:00.000Z', 'seed'),
('library', 'byala-roza', 'Не знам кое е по-ужасяващо – това, че някой е написал това, или че се припознавам. 😭', '2025-05-25T14:01:00.000Z', 'seed');
